//! Content model for the Juokseva Johtaja podcast site.
//!
//! The types in [`model`] use `&'static` data so the site can compile the whole episode catalogue into the
//! WebAssembly binary (generated by `site/build.rs` through [`codegen`]). The `parse` feature adds the
//! build-time reader for `episodes.yaml` and the episode markdown files.

pub mod codegen;
pub mod date;
pub mod escape;
pub mod feed;
pub mod model;
pub mod seo;
pub mod time;

#[cfg(feature = "parse")]
pub mod parse;

pub use date::Date;
pub use model::{Catalog, Episode, Guest, Highlight, Podcast};
